import type {RefObject} from 'react';
import {useEffect} from 'react';

export type UseListActiveElementScrollProps = {
    scrollableContainerRef: RefObject<HTMLElement>;
    containerTopOffset?: number;
    getActiveElement: () => HTMLElement | null | undefined;
};

export function useListActiveElementScroll({
    scrollableContainerRef,
    containerTopOffset = 0,
    getActiveElement,
}: UseListActiveElementScrollProps): void {
    useEffect(() => {
        const scrollableContainer = scrollableContainerRef.current;

        if (!scrollableContainer) {
            return;
        }

        const activeElement = getActiveElement();

        if (!activeElement) {
            return;
        }

        const activeElementBottom = activeElement.offsetTop + activeElement.offsetHeight;

        const {scrollTop: scrollableContainerTop, offsetHeight: scrollableContainerHeight} =
            scrollableContainer;
        const scrollableContainerBottom = scrollableContainerTop + scrollableContainerHeight;

        if (scrollableContainerBottom < activeElementBottom) {
            scrollableContainer.scrollTo({
                top: activeElementBottom - scrollableContainerHeight,
                behavior: 'auto',
            });
        } else if (activeElement.offsetTop - containerTopOffset < scrollableContainerTop) {
            scrollableContainer.scrollTo({
                top: activeElement.offsetTop - activeElement.offsetHeight,
                behavior: 'auto',
            });
        }
    }, [scrollableContainerRef, getActiveElement, containerTopOffset]);
}
